using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Globalization;
using System.Windows.Forms;
namespace ZenForms.Core
{
    public sealed class ZenColumnProfile { public string ColumnName { get; internal set; } public string DataType { get; internal set; } public int Rows { get; internal set; } public int Missing { get; internal set; } public int Unique { get; internal set; } public string Minimum { get; internal set; } public string Maximum { get; internal set; } public double Completeness { get { return Rows == 0 ? 0 : 100.0 * (Rows - Missing) / Rows; } } }
    [Category("ZenForms Modern Components")]
    [Description("DataTable profiler featuring completeness, missing values, cardinality, and numerical statistics.")]
    public class ZenDataProfiler : UserControl
    {
        private readonly DataGridView grid; private readonly Label summary; private DataTable source;
        [Browsable(false)] public IList<ZenColumnProfile> Profiles { get; private set; } = new List<ZenColumnProfile>();
        public event EventHandler ProfilingCompleted;
        public ZenDataProfiler() { Size = new Size(720, 420); BackColor = ZenTheme.Background; Panel top = new Panel { Dock = DockStyle.Top, Height = 44, BackColor = ZenTheme.Surface }; Button load = new Button { Dock = DockStyle.Left, Width = 118, Text = "Load CSV…", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground }; Button analyze = new Button { Dock = DockStyle.Left, Width = 95, Text = "Analize", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground }; summary = new Label { Dock = DockStyle.Fill, Text = "Load a DataTable or CSV", ForeColor = ZenTheme.Muted, TextAlign = ContentAlignment.MiddleRight, Padding = new Padding(0, 0, 10, 0) }; top.Controls.Add(summary); top.Controls.Add(analyze); top.Controls.Add(load); grid = new DataGridView { Dock = DockStyle.Fill, ReadOnly = true, AllowUserToAddRows = false, AllowUserToDeleteRows = false, AllowUserToResizeRows = false, RowHeadersVisible = false, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill, BackgroundColor = ZenTheme.Background, BorderStyle = BorderStyle.None, GridColor = ZenTheme.Border, EnableHeadersVisualStyles = false, SelectionMode = DataGridViewSelectionMode.FullRowSelect }; grid.ColumnHeadersDefaultCellStyle.BackColor = ZenTheme.SurfaceRaised; grid.ColumnHeadersDefaultCellStyle.ForeColor = ZenTheme.Foreground; grid.ColumnHeadersDefaultCellStyle.Font = new Font("Segoe UI Semibold", 8.5f); grid.DefaultCellStyle.BackColor = ZenTheme.Surface; grid.DefaultCellStyle.ForeColor = ZenTheme.Foreground; grid.DefaultCellStyle.SelectionBackColor = ZenTheme.Primary; grid.DefaultCellStyle.SelectionForeColor = Color.White; Controls.Add(grid); Controls.Add(top); load.Click += (s, e) => LoadCsv(); analyze.Click += (s, e) => Analyze(); }
        [Browsable(false)] public DataTable SourceTable { get { return source; } set { source = value; Analyze(); } }
        public void Analyze() { if (grid == null || source == null) return; List<ZenColumnProfile> profiles = new List<ZenColumnProfile>(); grid.Columns.Clear(); grid.Rows.Clear(); grid.Columns.Add("Column", "COLUMN"); grid.Columns.Add("Type", "TYPE"); grid.Columns.Add("Missing", "MISSING"); grid.Columns.Add("Unique", "UNIQUES"); grid.Columns.Add("Min", "MIN"); grid.Columns.Add("Max", "MAX"); grid.Columns.Add("Complete", "COMPLETUDE"); foreach (DataColumn col in source.Columns) { HashSet<string> unique = new HashSet<string>(StringComparer.Ordinal); int missing = 0; double min = Double.PositiveInfinity, max = Double.NegativeInfinity; bool numeric = IsNumeric(col.DataType); foreach (DataRow row in source.Rows) { object value = row[col]; if (value == null || value == DBNull.Value) { missing++; continue; } unique.Add(Convert.ToString(value, CultureInfo.InvariantCulture)); if (numeric) { double d = Convert.ToDouble(value, CultureInfo.InvariantCulture); if (!Double.IsNaN(d)) { min = Math.Min(min, d); max = Math.Max(max, d); } } } ZenColumnProfile p = new ZenColumnProfile { ColumnName = col.ColumnName, DataType = col.DataType.Name, Rows = source.Rows.Count, Missing = missing, Unique = unique.Count, Minimum = numeric && min != Double.PositiveInfinity ? min.ToString("G6", CultureInfo.InvariantCulture) : "—", Maximum = numeric && max != Double.NegativeInfinity ? max.ToString("G6", CultureInfo.InvariantCulture) : "—" }; profiles.Add(p); int idx = grid.Rows.Add(p.ColumnName, p.DataType, p.Missing, p.Unique, p.Minimum, p.Maximum, p.Completeness.ToString("0.0") + "%"); if (p.Completeness < 80) grid.Rows[idx].DefaultCellStyle.ForeColor = ZenTheme.Danger; } Profiles = profiles; summary.Text = source.Rows.Count.ToString("N0") + " lines    •    " + source.Columns.Count + " columns    •    " + source.Rows.Count * source.Columns.Count + " cells"; EventHandler h = ProfilingCompleted; if (h != null) h(this, EventArgs.Empty); }
        private void LoadCsv() { using (OpenFileDialog d = new OpenFileDialog { Filter = "CSV|*.csv;*.tsv;*.txt|Todos|*.*" }) if (d.ShowDialog(FindForm()) == DialogResult.OK) { try { SourceTable = ReadDelimited(d.FileName); } catch (Exception ex) { MessageBox.Show(FindForm(), ex.Message, "ZenDataProfiler", MessageBoxButtons.OK, MessageBoxIcon.Warning); } } }
        private static DataTable ReadDelimited(string path) { string[] lines = System.IO.File.ReadAllLines(path); DataTable t = new DataTable(System.IO.Path.GetFileNameWithoutExtension(path)); if (lines.Length == 0) return t; char delimiter = path.EndsWith(".tsv", StringComparison.OrdinalIgnoreCase) ? '\t' : (lines[0].Contains(";") && !lines[0].Contains(",") ? ';' : ','); string[] headers = SplitCsv(lines[0], delimiter); foreach (string h in headers) t.Columns.Add(String.IsNullOrWhiteSpace(h) ? "Column" + (t.Columns.Count + 1) : h.Trim()); for (int i = 1; i < lines.Length; i++) { if (String.IsNullOrWhiteSpace(lines[i])) continue; string[] cells = SplitCsv(lines[i], delimiter); DataRow row = t.NewRow(); for (int j = 0; j < t.Columns.Count && j < cells.Length; j++) row[j] = cells[j]; t.Rows.Add(row); } return t; }
        private static string[] SplitCsv(string line, char delimiter) { List<string> result = new List<string>(); System.Text.StringBuilder b = new System.Text.StringBuilder(); bool quote = false; for (int i = 0; i < line.Length; i++) { char c = line[i]; if (c == '"') { if (quote && i + 1 < line.Length && line[i + 1] == '"') { b.Append('"'); i++; } else quote = !quote; } else if (c == delimiter && !quote) { result.Add(b.ToString()); b.Clear(); } else b.Append(c); } result.Add(b.ToString()); return result.ToArray(); }
        private static bool IsNumeric(Type t) { return t == typeof(byte) || t == typeof(sbyte) || t == typeof(short) || t == typeof(ushort) || t == typeof(int) || t == typeof(uint) || t == typeof(long) || t == typeof(ulong) || t == typeof(float) || t == typeof(double) || t == typeof(decimal); }
    }
}

